INSERT INTO stage3_question_backfill VALUES
  ('fault_timing_after_start', 'Hata ortaya çıkmadan önce cihazın çalışma durumu hangisine uyuyor: başlar başlamaz, bir süre çalıştıktan sonra, yoksa aralıklı?', 'fault_timing_after_start', 78, '["immediate", "after_some_time", "intermittent", "unknown"]'::jsonb),
  ('display_temperature_rise', 'Hata öncesinde ekrandaki sıcaklığın normalden çok hızlı yükseldiğini gözlüyor musunuz?', 'display_temperature_rise', 76, '["yes", "no", "unknown"]'::jsonb),
  ('ignition_attempt_sequence', 'Cihazın ısı vermeye çalışırkenki davranışı hangisine uyuyor: tık sesleri var ama ısı yok, sessizken hemen hata, yoksa kısa süre ısı verip kesilme?', 'ignition_attempt_sequence', 75, '["clicks_no_heat", "silent_immediate", "brief_heat_then_fault", "unknown"]'::jsonb),
  ('heating_dhw_scope', 'Sorun hangi kullanımda görülüyor: yalnız kalorifer, yalnız sıcak su, yoksa her ikisinde?', 'heating_dhw_scope', 74, '["heating_only", "dhw_only", "both", "unknown"]'::jsonb);
