INSERT INTO stage3_effect_backfill VALUES
  ('stage3_copa_01ae9dbab70d0b1147b4', 'Fan sorunu', 'E51', 'abnormal_fan_noise', 'yes', 'support', 'Fan Rotoru Kilitlenme Arızası', 'Çalışma girişimindeki olağandışı sürtme/uğultu, mevcut fan/mekanik hava hareketi adayını göreli güçlendirir; diğer ses kaynakları ve sessiz fan arızası dışlanmaz.', 'Candidate source basis: "Fan Rotoru Kilitlenme Arızası". Process inference: Çalışma girişimindeki olağandışı sürtme/uğultu, mevcut fan/mekanik hava hareketi adayını göreli güçlendirir; diğer ses kaynakları ve sessiz fan arızası dışlanmaz. Bu göreli süreç çıkarımıdır; kesin teşhis veya kaynakta birebir verilen belirti-parça ilişkisi değildir.', 'https://www.copa.com.tr/tr/images/dokumanlar/140/dokuman.pdf'),
  ('stage3_copa_0351d68006bf91e077ac', 'Fan sorunu', 'E30', 'abnormal_fan_noise', 'yes', 'support', 'Reset ile yeniden deneyin; hata sürerse fan kontrol edilmelidir.', 'Çalışma girişimindeki olağandışı sürtme/uğultu, mevcut fan/mekanik hava hareketi adayını göreli güçlendirir; diğer ses kaynakları ve sessiz fan arızası dışlanmaz.', 'Candidate source basis: "Reset ile yeniden deneyin; hata sürerse fan kontrol edilmelidir.". Process inference: Çalışma girişimindeki olağandışı sürtme/uğultu, mevcut fan/mekanik hava hareketi adayını göreli güçlendirir; diğer ses kaynakları ve sessiz fan arızası dışlanmaz. Bu göreli süreç çıkarımıdır; kesin teşhis veya kaynakta birebir verilen belirti-parça ilişkisi değildir.', 'https://www.copa.com.tr/tr/images/dokumanlar/140/dokuman.pdf'),
  ('stage3_copa_045bf09ae2ddb9eff9c1', 'Fan sorunu', 'E06', 'abnormal_fan_noise', 'yes', 'support', 'Bu durum fan veya eşanjör sisteminde arızaya işaret edebilir.', 'Çalışma girişimindeki olağandışı sürtme/uğultu, mevcut fan/mekanik hava hareketi adayını göreli güçlendirir; diğer ses kaynakları ve sessiz fan arızası dışlanmaz.', 'Candidate source basis: "Bu durum fan veya eşanjör sisteminde arızaya işaret edebilir.". Process inference: Çalışma girişimindeki olağandışı sürtme/uğultu, mevcut fan/mekanik hava hareketi adayını göreli güçlendirir; diğer ses kaynakları ve sessiz fan arızası dışlanmaz. Bu göreli süreç çıkarımıdır; kesin teşhis veya kaynakta birebir verilen belirti-parça ilişkisi değildir.', 'https://www.copa.com.tr/tr/images/dokumanlar/140/dokuman.pdf'),
  ('stage3_copa_04ffc92aca9153012c0e', 'Termostat/sıcaklık sınırlayıcısı sorunu', 'E09', 'display_temperature_rise', 'yes', 'support', 'Aşırı Isınma Termostat Arızası', 'Hata öncesi kullanıcı ekranındaki olağandışı hızlı sıcaklık artışı, bu ısıl hata bağlamında ısı uzaklaştırma/koruma adayını göreli güçlendirir; gösterge yanılabilir ve parça arızası kanıtlanmaz.', 'Candidate source basis: "Aşırı Isınma Termostat Arızası". Process inference: Hata öncesi kullanıcı ekranındaki olağandışı hızlı sıcaklık artışı, bu ısıl hata bağlamında ısı uzaklaştırma/koruma adayını göreli güçlendirir; gösterge yanılabilir ve parça arızası kanıtlanmaz. Bu göreli süreç çıkarımıdır; kesin teşhis veya kaynakta birebir verilen belirti-parça ilişkisi değildir.', 'https://www.copa.com.tr/tr/images/dokumanlar/106/dokuman.pdf'),
  ('stage3_copa_04ffc92aca9153012c0e', 'Termostat/sıcaklık sınırlayıcısı sorunu', 'E09', 'fault_timing_after_start', 'after_some_time', 'support', 'Aşırı Isınma Termostat Arızası', 'Cihazın bir süre çalışıp ısındıktan sonra hata vermesi, bu hata kaydındaki ısıl koruma/ısı transferi/dolaşım noktasını göreli güçlendirir; baştan arızalı koruma da mümkündür.', 'Candidate source basis: "Aşırı Isınma Termostat Arızası". Process inference: Cihazın bir süre çalışıp ısındıktan sonra hata vermesi, bu hata kaydındaki ısıl koruma/ısı transferi/dolaşım noktasını göreli güçlendirir; baştan arızalı koruma da mümkündür. Bu göreli süreç çıkarımıdır; kesin teşhis veya kaynakta birebir verilen belirti-parça ilişkisi değildir.', 'https://www.copa.com.tr/tr/images/dokumanlar/106/dokuman.pdf'),
  ('stage3_copa_06910e3d83044905c1be', 'Yüksek limit / termik koruma noktası', 'E06', 'display_temperature_rise', 'yes', 'support', 'Tesisat Devresinde Aşırı Sıcaklık', 'Hata öncesi kullanıcı ekranındaki olağandışı hızlı sıcaklık artışı, bu ısıl hata bağlamında ısı uzaklaştırma/koruma adayını göreli güçlendirir; gösterge yanılabilir ve parça arızası kanıtlanmaz.', 'Candidate source basis: "Tesisat Devresinde Aşırı Sıcaklık". Process inference: Hata öncesi kullanıcı ekranındaki olağandışı hızlı sıcaklık artışı, bu ısıl hata bağlamında ısı uzaklaştırma/koruma adayını göreli güçlendirir; gösterge yanılabilir ve parça arızası kanıtlanmaz. Bu göreli süreç çıkarımıdır; kesin teşhis veya kaynakta birebir verilen belirti-parça ilişkisi değildir.', 'https://www.copa.com.tr/tr/images/dokumanlar/59/dokuman.pdf'),
  ('stage3_copa_06910e3d83044905c1be', 'Yüksek limit / termik koruma noktası', 'E06', 'fault_timing_after_start', 'after_some_time', 'support', 'Tesisat Devresinde Aşırı Sıcaklık', 'Cihazın bir süre çalışıp ısındıktan sonra hata vermesi, bu hata kaydındaki ısıl koruma/ısı transferi/dolaşım noktasını göreli güçlendirir; baştan arızalı koruma da mümkündür.', 'Candidate source basis: "Tesisat Devresinde Aşırı Sıcaklık". Process inference: Cihazın bir süre çalışıp ısındıktan sonra hata vermesi, bu hata kaydındaki ısıl koruma/ısı transferi/dolaşım noktasını göreli güçlendirir; baştan arızalı koruma da mümkündür. Bu göreli süreç çıkarımıdır; kesin teşhis veya kaynakta birebir verilen belirti-parça ilişkisi değildir.', 'https://www.copa.com.tr/tr/images/dokumanlar/59/dokuman.pdf'),
  ('stage3_copa_07198ae0bd10d43c4b79', 'Su kaçağı/sızıntısı sorunu', 'E08', 'visible_water_leak', 'yes', 'support', 'hata sık tekrarlıyorsa tesisat devresinde su kaçağı olabilir.', 'Dışarıdan gözlenen su kaçağı kaynakta tanımlı sızıntı noktasını göreli güçlendirir; kaçağın yeri kesinleşmez.', 'Candidate source basis: "hata sık tekrarlıyorsa tesisat devresinde su kaçağı olabilir.". Process inference: Dışarıdan gözlenen su kaçağı kaynakta tanımlı sızıntı noktasını göreli güçlendirir; kaçağın yeri kesinleşmez. Bu göreli süreç çıkarımıdır; kesin teşhis veya kaynakta birebir verilen belirti-parça ilişkisi değildir.', 'https://www.copa.com.tr/tr/images/dokumanlar/59/dokuman.pdf'),
  ('stage3_copa_0b25184066c8fde07079', 'Kullanım suyu sıcaklık sensörü sorunu', 'E04', 'heating_dhw_scope', 'dhw_only', 'support', 'Kullanım Suyu Sensörü Arızası', 'Kalorifer normal iken yalnız kullanım suyunda sorun görülmesi, kaynakta kullanım suyu/boyler devresine bağlı noktayı göreli güçlendirir; ortak kontrol arızası dışlanmaz.', 'Candidate source basis: "Kullanım Suyu Sensörü Arızası". Process inference: Kalorifer normal iken yalnız kullanım suyunda sorun görülmesi, kaynakta kullanım suyu/boyler devresine bağlı noktayı göreli güçlendirir; ortak kontrol arızası dışlanmaz. Bu göreli süreç çıkarımıdır; kesin teşhis veya kaynakta birebir verilen belirti-parça ilişkisi değildir.', 'https://www.copa.com.tr/tr/images/dokumanlar/140/dokuman.pdf'),
  ('stage3_copa_0b25184066c8fde07079', 'Kullanım suyu sıcaklık sensörü sorunu', 'E04', 'heating_dhw_scope', 'heating_only', 'weaken', 'Kullanım Suyu Sensörü Arızası', 'Kullanım suyu normal iken yalnız kaloriferde sorun görülmesi, kullanım suyu/boyler noktasını göreli zayıflatır; kilitleme ve ortak kontrol ihtimali nedeniyle dışlanmaz.', 'Candidate source basis: "Kullanım Suyu Sensörü Arızası". Process inference: Kullanım suyu normal iken yalnız kaloriferde sorun görülmesi, kullanım suyu/boyler noktasını göreli zayıflatır; kilitleme ve ortak kontrol ihtimali nedeniyle dışlanmaz. Bu göreli süreç çıkarımıdır; kesin teşhis veya kaynakta birebir verilen belirti-parça ilişkisi değildir.', 'https://www.copa.com.tr/tr/images/dokumanlar/140/dokuman.pdf'),
